export class PlacementsComponent {
  apiService;
  drives = [];
  plans = [];
  applications = [];
  showModal = false;
  editingDrive = null;
  saving = false;
  errorMessage = '';
  driveTab = 'basic';
  driveForm = {
    companyName: '',
    role: '',
    driveType: 'EXTERNAL',
    packageAmount: null,
    location: '',
    eligibility: '',
    description: '',
    applyLink: '',
    deadline: '',
    isActive: true,
    planId: null
  };
  showSlotsModal = false;
  slotsForDrive = null;
  slots = [];
  newSlot = {
    slotTime: '',
    location: '',
    notes: ''
  };
  showCriteriaModal = false;
  criteriaDrive = null;
  criteria = {
    minAttendance: null,
    minCourseCompletion: null,
    minAssignmentAvg: null,
    minExamAvg: null
  };
  savingCriteria = false;
  criteriaMessage = '';
  constructor(apiService) {
    this.apiService = apiService;
  }
  ngOnInit() {
    this.loadDrives();
    this.loadPlans();
    this.loadApplications();
  }
  loadApplications() {
    this.apiService.get('/api/student-placements').subscribe({
      next: data => {
        this.applications = data;
      },
      error: err => {
        console.error('Failed to load applications', err);
        this.applications = [];
      }
    });
  }
  updateApplicationStatus(application, status) {
    this.apiService.put(`/api/student-placements/${application.id}/status`, {
      status
    }).subscribe({
      next: () => {
        application.status = status;
      },
      error: err => {
        console.error('Failed to update status', err);
        alert('Failed to update application status.');
      }
    });
  }
  loadDrives() {
    this.apiService.get('/api/placement-drives').subscribe({
      next: data => {
        this.drives = data;
      },
      error: err => {
        console.error('Failed to load drives', err);
        this.drives = [];
      }
    });
  }
  loadPlans() {
    this.apiService.get('/api/subscription-plans/admin/all').subscribe({
      next: data => {
        this.plans = data;
      },
      error: err => {
        console.error('Failed to load subscription plans', err);
        this.plans = [];
      }
    });
  }
  getPlanName(planId) {
    if (!planId) return '';
    const plan = this.plans.find(p => p.id === planId);
